    return (item_count + page_size - 1) // page_size


def is_valid_page(page: Optional[int], item_count, page_size):
    if page is None:
        return False
    total = _total_pages(item_count, page_size)
    return 0 <= page < total

attempts.test_code:
def test_is_valid_page_standard_behavior():
    assert is_valid_page(10, 5, 2) == True

def test_is_valid_page_edge_case():
    assert is_valid_page(None, 5, 2) == False

